    check(!before?.detail.includes("'holding'"), `350: doctor named a Book that has its manifest: ${JSON.stringify(before)}`);
    equal(cli(['shelf', 'rebuild', 'empty-one']).exit, 0, '350: shelf rebuild empty-one failed');
    const after = row();
